function tetoFollowupDia(estagio, limite, enviadosHoje, hoje) {
  const F = CONFIG.followup;
  const espaco = Math.max(0, Number(limite || 0) - Number(enviadosHoje || 0));
  if (estagio === 'sombra') return F.sombraMaxTextos;
