function checarRamo(texto, lead) {
  const temTipo = !!(lead.tipo_google || (lead.tipos_google || []).length);
  const evid = norm([lead.nome, lead.tipo_google, ...(lead.tipos_google || []), temTipo ? '' : String(lead.nicho || '').replace(/_/g, ' ')].join(' '));
