const TIPO_VAREJO_RE = /\b(loja|agropecu|pet ?shop|material de constru|ferrag|mercad|supermercad|boutique|papelaria|distribuidora|atacad|varejo|ra[çc][õo]es|[óo]tica|farm[áa]cia|drogaria)/i;
