const TIPOS_SERVICO_RE = /^(pet_care|veterinary_care|beauty_salon|hair_care|spa|car_repair|car_wash|dentist|doctor|physiotherapist|gym|lawyer|accounting|school|driving_school)$/;
function ehVarejo(lead) {
