// Assunto: formato sorteado (3 a 7 palavras, nome e cidade contam 1 cada), sem nota/avaliações nem os padrões antigos.
const ASSUNTO_PROIBIDO_V2 = /\b(pode aparecer|sem site|ganha|tem nota|presenca digital)\b/;
