  const nFmt = norm(fmt.replace(/\{\w+\}/g, ' ')).split(' ').filter(Boolean).length + (fmt.match(/\{\w+\}/g) || []).length;
  if (nFmt < 3 || nFmt > 7) erros.push(`formato do config fora de 3-7 palavras ("${fmt}")`);
