  const toks = fmt.split(/(\{nome\}|\{cidade\})/)
    .map((p) => (p === '{nome}' ? '(.+?)' : p === '{cidade}' ? escRe(norm(lead.cidade)) : escRe(norm(p)))).filter(Boolean);
  const m = n.match(new RegExp('^' + toks.join(' ') + '$'));
