  const slot = m ? m[1].split(' ').filter((w, i) => !(i === 0 && ['a', 'o', 'as', 'os'].includes(w))) : [];
  if (!m || slot.length < 1 || slot.length > 4 || !slot.every((w) => doNome.has(w))) erros.push(`fora do formato sorteado ("${fmt}")`);
  return erros.map((e) => 'assunto ' + e);
