  if (!temMarca && palavras.length >= 2 && palavras.length <= 3 && palavras.every((w) => /^[a-z]+$/.test(w))
      && palavras.slice(1).some((w) => SOBRENOMES_COMUNS.has(w))) return 'pessoa_fisica';
