  // completo 36, contato.completo 6, sem_conectivos 1, contato.sem_conectivos 0. A verificação para no 1º confirmado.
  const porPadrao = { completo: `${completo}@gmail.com`, 'contato.completo': `contato.${completo}@gmail.com` };
